// O Supabase entrega o QR como `data:img/svg+xml;utf-8,<?xml …?><!-- Generated by SVGo --><svg width height>…`
// (prefixo "img", não "image"; cabeçalho XML e comentário antes do <svg>; sem viewBox).
const PREFIX = /^data:(?:image|img)\/svg\+xml(;[^,]*)?,/;

/** Extrai só o elemento <svg> e garante um viewBox, para o SvgXml desenhar em qualquer tamanho. */
export function svgFromDataUrl(dataUrl: string): string | null {
  let body = dataUrl.trim();
  if (body.startsWith('data:')) {
    if (!PREFIX.test(body)) return null;
    body = body.replace(PREFIX, '');
  }
  if (body.startsWith('%3C')) {
    try {
      body = decodeURIComponent(body);
    } catch {
      return null;
    }
  }
  const start = body.indexOf('<svg');
  // Antes do <svg> só pode haver declaração XML, comentários e espaços.
  if (start < 0 || body.slice(0, start).replace(/<\?xml[^>]*\?>|<!--[\s\S]*?-->|\s/g, '') !== '') return null;
  return withViewBox(body.slice(start).trim());
}

function withViewBox(svg: string): string {
  const open = svg.match(/^<svg\b[^>]*>/);
  if (!open || /\bviewBox=/.test(open[0])) return svg;
  const width = open[0].match(/\bwidth="(\d+(?:\.\d+)?)"/)?.[1];
  const height = open[0].match(/\bheight="(\d+(?:\.\d+)?)"/)?.[1];
  if (!width || !height) return svg;
  return svg.replace(/^<svg\b/, `<svg viewBox="0 0 ${width} ${height}"`);
}
